result:
.processAnalysisContainer {
  height: calc(100vh - 90px);
}

.processAnalysisContainer {
  display: flex;
  background: #ffffff;
  flex-direction: column;
  padding: 16px 24px 46px 24px;
}

.viewList {
  position: absolute;
  font-weight: 400;
  font-size: 14px;
  color: #545672;
  right: 0;
  top: 50px;
}

.pageTop {
  width: 100%;
  display: flex;
  flex-direction: row;
  position: relative;
  padding-bottom: 24px;
  margin-top: 5px;
}

.pageTop ::v-deep .el-select {
  width: 200px;
  height: 32px;
  background: #ffffff;
  border-radius: 2px;
}

.pageTop .search-input {
  padding-right: 24px;
}

.pageTop .el-select.search-input,
.pageTop .search-input.el-date-editor.el-input,
.pageTop .search-input.el-date-editor.el-input__inner {
  width: 200px;
}

.pageTop .search-input ::v-deep .el-input__icon {
  line-height: 32px;
  height: 32px;
}

.pageBottom {
  width: 100%;
  margin-top: 50px;
  height: calc(100% - 80px);
  display: flex;
  align-items: center;
  justify-content: center;
}

.checkedProcessTable ::v-deep .cell {
  font-family: PingFangSC-Regular;
  font-weight: 400;
  font-size: 14px;
  color: #333651;
}

.checkedProcessTable ::v-deep .el-table__body-wrapper .cell {
  color: #1b7cef;
  cursor: pointer;
}

.checkedProcessTable ::v-deep .is-center .cell,
.checkedProcessTable ::v-deep .is-left .cell {
  color: #333651;
  cursor: auto;
}

.el-dialog {
  width: 60%;
  height: 60%;
  max-height: 700px;
  padding: 0;
}

::v-deep .el-dialog__title {
  color: #333651;
}

::v-deep .el-dialog__body {
  padding: 21px 24px 12px 24px;
  width: 100%;
  height: calc(100% - 98px);
}

::v-deep .el-table--scrollable-y .el-table__body-wrapper:hover {
  overflow-x: hidden !important;
}

.filter-btn.flex {
  padding-bottom: 24px;
}

.header-title .titleName {
  font-family: PingFangSC-Regular;
  font-weight: 400;
  font-size: 16px;
  color: #333651;
  display: inline-block;
  width: 200px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.filter-btn.flex ::v-deep .el-input {
  width: auto;
}

.filter-btn.flex ::v-deep .el-input__inner {
  width: 160px;
  height: 32px;
  background: #ffffff;

  border-radius: 2px;
  margin-right: 8px;
}

.taskStatusList ::v-deep .is-center .cell {
  position: relative;
  left: -24px;
}

.taskStatusList ::v-deep .cell {
  font-family: PingFangSC-Regular;
  font-weight: 400;
  font-size: 14px;
  color: #333651;
}

.empty-text {
  line-height: 60px;
  color: #909399;
}

::v-deep .el-dialog .el-loading-mask {
  height: 100% !important;
}

.ml1 {
  margin-left: 10px;
}
